<template>
  <MainLayout>
    <div class="rate-page">
      <header class="heading"><div><p class="eyebrow">FINANCE / FX</p><h1>汇率管理</h1><p>每天 9:30 自动获取最新汇率。</p></div><div class="actions"><div class="picker currency-picker"><button class="picker-button" @click="pickerOpen = pickerOpen === 'currency' ? '' : 'currency'">{{ currency }}<i class="picker-caret" aria-hidden="true"></i></button><div v-if="pickerOpen === 'currency'" class="picker-menu"><button v-for="value in currencies" :key="value" :class="{ selected: currency === value }" @click="currency = value; pickerOpen = ''; load()">{{ value }}<span v-if="currency === value">✓</span></button></div></div><button v-if="isRefreshAdmin" class="primary" @click="refresh" :disabled="refreshing">{{ refreshing ? '获取中…' : '获取最新汇率' }}</button><button @click="load" :disabled="loading">刷新</button></div></header>
      <p v-if="message" class="message">{{ message }}</p><p v-if="error" class="error">{{ error }}</p>
      <section class="chart-card">
        <div class="card-title"><strong>{{ currency }} / CNY 汇率趋势</strong><span>每日汇率</span></div>
        <div class="chart-controls">
          <div class="range-tabs"><button v-for="option in chartRanges" :key="option.value" :class="{ chosen: chartRange === option.value }" @click="chartRange = option.value; hoverIndex = null">{{ option.label }}</button></div>
          <div v-if="chartRange !== 'all'" class="picker-group"><div class="picker"><button class="picker-button" @click="pickerOpen = pickerOpen === 'chart-year' ? '' : 'chart-year'">{{ chartYear }}年<i class="picker-caret" aria-hidden="true"></i></button><div v-if="pickerOpen === 'chart-year'" class="picker-menu"><button v-for="year in years" :key="year" @click="chartYear = year; pickerOpen = ''; hoverIndex = null">{{ year }}年</button></div></div><div v-if="chartRange === 'month'" class="picker"><button class="picker-button" @click="pickerOpen = pickerOpen === 'chart-month' ? '' : 'chart-month'">{{ Number(chartMonth.slice(5)) }}月<i class="picker-caret" aria-hidden="true"></i></button><div v-if="pickerOpen === 'chart-month'" class="picker-menu month-menu"><button v-for="month in 12" :key="month" @click="chartMonth = `${chartYear}-${String(month).padStart(2, '0')}`; pickerOpen = ''; hoverIndex = null">{{ month }}月</button></div></div></div>
        </div>
        <div v-if="chartItems.length" class="chart-wrap">
          <svg viewBox="0 0 960 300" role="img" aria-label="每日汇率趋势，可使用左右方向键查看" tabindex="0" @pointermove="hoverChart" @pointerleave="hoverIndex = null" @keydown.left.prevent="stepHover(-1)" @keydown.right.prevent="stepHover(1)">
            <defs><linearGradient id="fx-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3885b0" stop-opacity=".24"/><stop offset="100%" stop-color="#3885b0" stop-opacity=".015"/></linearGradient></defs>
            <g v-for="tick in chartTicks" :key="tick"><line x1="64" :y1="chartY(tick)" x2="930" :y2="chartY(tick)" class="grid-line"/><text x="54" :y="chartY(tick) + 4" text-anchor="end" class="axis-label">{{ tick.toFixed(3) }}</text></g>
            <path :d="areaPath" fill="url(#fx-area)"/><polyline :points="linePoints" class="trend-line"/>
            <text v-for="tick in dateTicks" :key="tick.index" :x="point(tick.index).x" y="280" text-anchor="middle" class="axis-label">{{ tick.label }}</text>
            <g v-if="hovered"><line :x1="point(hovered.index).x" :x2="point(hovered.index).x" y1="40" y2="248" stroke="#9bb1c0" stroke-dasharray="4 4"/><circle :cx="point(hovered.index).x" :cy="point(hovered.index).y" r="5" fill="#285d83" stroke="white" stroke-width="2"/><g :transform="`translate(${Math.max(66, Math.min(746, point(hovered.index).x - 92))}, 2)`"><rect width="184" height="30" rx="5" fill="#edf3f7"/><text x="92" y="20" text-anchor="middle" class="tooltip-text">{{ hovered.item.date }} · {{ rateText(hovered.item.rate) }}</text></g></g>
          </svg>
        </div><p v-else class="empty">所选时间段暂无汇率数据</p>
      </section>
      <section class="calendar-card"><div class="card-title"><div><strong>汇率日历</strong><div class="calendar-pickers"><div class="picker"><button class="picker-button" @click="pickerOpen = pickerOpen === 'calendar-year' ? '' : 'calendar-year'">{{ calendarYear }}年<i class="picker-caret" aria-hidden="true"></i></button><div v-if="pickerOpen === 'calendar-year'" class="picker-menu"><button v-for="year in years" :key="year" @click="calendarYear = year; pickerOpen = ''; syncCalendarMonth()">{{ year }}年</button></div></div><div class="picker"><button class="picker-button" @click="pickerOpen = pickerOpen === 'calendar-month' ? '' : 'calendar-month'">{{ calendarMonthNumber }}月<i class="picker-caret" aria-hidden="true"></i></button><div v-if="pickerOpen === 'calendar-month'" class="picker-menu month-menu"><button v-for="month in 12" :key="month" @click="calendarMonthNumber = month; pickerOpen = ''; syncCalendarMonth()">{{ month }}月</button></div></div><button class="today-button" @click="goToday">今天</button></div></div><div class="month-nav"><button aria-label="上个月" @click="moveMonth(-1)">‹</button><button aria-label="下个月" @click="moveMonth(1)">›</button></div></div><div class="calendar-week"><span v-for="day in weekDays" :key="day">{{ day }}</span></div><div class="calendar-grid"><div v-for="cell in calendarCells" :key="cell.key" class="day-cell" :class="{ muted: !cell.inMonth, today: cell.key === todayDate, empty: !cell.item }" :title="cell.item ? `${cell.item.date} · 1 ${currency} = ¥${rateText(cell.item.rate)}` : ''"><span>{{ cell.day }}</span><b v-if="cell.item">{{ rateText(cell.item.rate) }}</b><i v-if="cell.item" :style="{ opacity: rateOpacity(cell.item.rate) }"></i></div></div></section>
    </div>
  </MainLayout>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import MainLayout from '@/components/layout/MainLayout.vue'
import request from '@/utils/request'
const currencies = ['USD', 'EUR', 'CAD', 'GBP', 'MXN', 'CHF', 'PLN']; const currency = ref('USD'); const items = ref([]); const loading = ref(false); const refreshing = ref(false); const message = ref(''); const error = ref(''); const selectedItem = ref(null); const calendarMonth = ref(new Date().toLocaleDateString('sv-SE').slice(0, 7))
const weekDays = ['一', '二', '三', '四', '五', '六', '日']
const todayDate = new Date().toLocaleDateString('sv-SE')
const isRefreshAdmin = computed(() => { try { return JSON.parse(localStorage.getItem('user') || '{}').name === '管理员' } catch { return false } })
const rateText = value => Number(value).toFixed(5).replace(/0+$/, '').replace(/\.$/, '')
const sortedItems = computed(() => [...items.value].sort((a, b) => a.date.localeCompare(b.date)))
const chartRanges = [{ value: 'month', label: '月度' }, { value: 'year', label: '年度' }, { value: 'all', label: '全部' }]
const chartRange = ref('year')
const chartMonth = ref(new Date().toLocaleDateString('sv-SE').slice(0, 7))
const chartYear = ref(String(new Date().getFullYear()))
const hoverIndex = ref(null); const pickerOpen = ref('')
const years = computed(() => [...new Set([chartYear.value, ...sortedItems.value.map(item => item.date.slice(0, 4))])].sort().reverse())
const chartItems = computed(() => sortedItems.value.filter(item => chartRange.value === 'all' || item.date.startsWith(chartRange.value === 'month' ? chartMonth.value : chartYear.value)))
const rateValues = computed(() => chartItems.value.map(item => Number(item.rate)))
const chartMin = computed(() => rateValues.value.length ? Math.min(...rateValues.value) - padding.value : 0)
const padding = computed(() => rateValues.value.length ? Math.max((Math.max(...rateValues.value) - Math.min(...rateValues.value)) * .15, .001) : .001)
const chartMax = computed(() => rateValues.value.length ? Math.max(...rateValues.value) + padding.value : 1)
const chartSpan = computed(() => chartMax.value - chartMin.value)
const chartTicks = computed(() => Array.from({ length: 5 }, (_, i) => chartMin.value + chartSpan.value * i / 4))
const chartY = value => 248 - (value - chartMin.value) / chartSpan.value * 204
const timestamp = item => Date.parse(item.date + 'T00:00:00Z')
const point = index => { const rows = chartItems.value; const span = timestamp(rows[rows.length - 1]) - timestamp(rows[0]); return { x: span ? 64 + (timestamp(rows[index]) - timestamp(rows[0])) / span * 866 : 497, y: chartY(Number(rows[index].rate)) } }
const linePoints = computed(() => chartItems.value.map((_, i) => `${point(i).x},${point(i).y}`).join(' '))
const areaPath = computed(() => chartItems.value.length ? `M ${point(0).x},248 L ${linePoints.value} L ${point(chartItems.value.length - 1).x},248 Z` : '')
const dateTicks = computed(() => [...new Set(Array.from({ length: Math.min(5, chartItems.value.length) }, (_, i) => Math.round(i * (chartItems.value.length - 1) / Math.max(1, Math.min(5, chartItems.value.length) - 1))))].map(index => ({ index, label: chartRange.value === 'all' ? chartItems.value[index].date.slice(0, 7) : chartItems.value[index].date.slice(5) })))
const hovered = computed(() => { const index = Math.min(hoverIndex.value ?? chartItems.value.length - 1, chartItems.value.length - 1); return index >= 0 ? { index, item: chartItems.value[index] } : null })
function hoverChart(event) { const svg = event.currentTarget; const pt = svg.createSVGPoint(); pt.x = event.clientX; pt.y = event.clientY; const x = pt.matrixTransform(svg.getScreenCTM().inverse()).x; let nearest = 0; for (let i = 1; i < chartItems.value.length; i++) if (Math.abs(point(i).x - x) < Math.abs(point(nearest).x - x)) nearest = i; hoverIndex.value = nearest }
function stepHover(delta) { hoverIndex.value = Math.max(0, Math.min(chartItems.value.length - 1, (hoverIndex.value ?? chartItems.value.length - 1) + delta)) }
const calendarTitle = computed(() => calendarMonth.value ? calendarMonth.value.replace('-', '年') + '月' : '—'); const calendarYear = computed({ get: () => calendarMonth.value.slice(0, 4), set: value => { calendarMonth.value = `${value}-${String(calendarMonthNumber.value).padStart(2, '0')}` } }); const calendarMonthNumber = computed({ get: () => Number(calendarMonth.value.slice(5)), set: value => { calendarMonth.value = `${calendarYear.value}-${String(value).padStart(2, '0')}` } })
const calendarMap = computed(() => Object.fromEntries(items.value.map(item => [item.date, item])))
const calendarCells = computed(() => { if (!calendarMonth.value) return []; const [year, month] = calendarMonth.value.split('-').map(Number); const first = new Date(year, month - 1, 1); const offset = (first.getDay() + 6) % 7; const days = new Date(year, month, 0).getDate(); const cells = []; for (let i = 0; i < offset; i++) { const d = new Date(year, month - 1, -offset + i + 1); cells.push({ key: `prev-${i}`, day: d.getDate(), inMonth: false }) }; for (let day = 1; day <= days; day++) { const date = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`; cells.push({ key: date, day, inMonth: true, item: calendarMap.value[date] }) }; while (cells.length % 7) cells.push({ key: `next-${cells.length}`, day: cells.length - offset - days + 1, inMonth: false }); return cells })
const rateOpacity = () => 0.65
const fetchedText = item => item?.fetched_at ? new Date(item.fetched_at).toLocaleString('zh-CN', { hour12: false }) : '—'
function syncCalendarMonth() { calendarMonth.value = `${calendarYear.value}-${String(calendarMonthNumber.value).padStart(2, '0')}` }; function goToday() { const today = new Date().toLocaleDateString('sv-SE').slice(0, 7); calendarMonth.value = today; pickerOpen.value = '' }; function moveMonth(offset) { const [year, month] = calendarMonth.value.split('-').map(Number); const date = new Date(year, month - 1 + offset, 1); calendarMonth.value = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}` }
async function load() { loading.value = true; error.value = ''; try { const result = await request.get('/finance/exchange-rates', { params: { currency: currency.value } }); items.value = result.data.items || []; if (items.value.length) { selectedItem.value = sortedItems.value[sortedItems.value.length - 1]; calendarMonth.value = selectedItem.value.date.slice(0, 7); chartMonth.value = calendarMonth.value; chartYear.value = selectedItem.value.date.slice(0, 4) } } catch (e) { error.value = e.response?.data?.error || '汇率查询失败' } finally { loading.value = false } }
async function refresh() { refreshing.value = true; message.value = ''; error.value = ''; try { const result = await request.post('/finance/exchange-rates/refresh'); message.value = result.data.rate_count ? `${result.data.msg}（${result.data.count} 天，${result.data.rate_count} 条）` : result.data.msg; await load() } catch (e) { error.value = e.response?.data?.msg || e.response?.data?.error || '汇率刷新失败' } finally { refreshing.value = false } }
function closePicker(event) { if (!event.target.closest('.picker')) pickerOpen.value = '' }
onMounted(() => { load(); document.addEventListener('click', closePicker) })
onBeforeUnmount(() => document.removeEventListener('click', closePicker))
</script>
<style scoped>
