@media(max-width:700px){.rate-page{padding:24px 14px}.heading{align-items:flex-start;flex-direction:column;gap:16px}.actions{width:100%}.actions button{flex:1}.calendar-card,.chart-card{padding:14px}.day-cell{min-height:58px;padding:7px}.day-cell b{font-size:10px;margin-top:7px}.rate-detail{align-items:flex-start;flex-wrap:wrap}.rate-detail small{width:100%;margin-left:0}}
.chart-controls{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}.range-tabs{display:flex;gap:4px}.range-tabs button{border-color:transparent;background:transparent}.range-tabs .chosen{background:#eaf2f8;color:#245879;border-color:#c9dce9;font-weight:600}.picker-group,.calendar-pickers{display:flex;gap:6px;align-items:center}.picker{position:relative}.picker-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:30px;padding:0 11px;border:1px solid #d7e1e7;border-radius:6px;background:#fff;color:#38546a;font-size:12px;font-variant-numeric:tabular-nums}.picker-caret{display:inline-block;width:7px;height:7px;margin-top:-3px;border-right:1.5px solid #627b8c;border-bottom:1.5px solid #627b8c;transform:rotate(45deg);transition:transform .16s ease}.picker-button:hover .picker-caret{transform:rotate(225deg);margin-top:4px}.picker-button:hover{border-color:#8eb0c4;background:#f5f9fb}.picker-menu{position:absolute;z-index:10;top:36px;left:0;display:grid;grid-template-columns:repeat(2,1fr);min-width:112px;padding:5px;border:1px solid #d9e3e9;border-radius:8px;background:#fff;box-shadow:0 10px 24px rgb(28 55 75 / 13%)}.picker-menu button{display:flex;align-items:center;justify-content:space-between;width:100%;height:30px;padding:0 10px;border:0;border-radius:5px;background:transparent;color:#4a6071;font-size:12px;text-align:left}.picker-menu button:hover,.picker-menu button.selected{background:#edf5f9;color:#245879}.picker-menu button span{float:right;color:#285d83;font-weight:700}.currency-picker .picker-menu{right:0;left:auto;min-width:136px}.month-menu{grid-template-columns:repeat(3,1fr);min-width:150px}.today-button{height:30px;padding:0 10px;border:1px solid #d7e1e7;border-radius:6px;background:#f5f9fb;color:#38546a;font-size:12px}.tooltip-text{font-size:13px;fill:#24475e;font-variant-numeric:tabular-nums}.chart-wrap svg:focus-visible{outline:2px solid #7ca3bd;outline-offset:4px}.trend-line{stroke-width:2.3}button:disabled{opacity:.5;cursor:default}
</style>
